import { HomeSidebar } from '@/components/layout/sidebar/home-sidebar';
import { PageLayout } from '@/components/layout/page-layout';
import { LatestProductCard } from '@/components/products/latest-product-card';
import { Badge } from '@/components/ui/badge';
import { getCollectionProducts, getCollections, getProducts } from '@/lib/shopify';
import { getLabelPosition } from '../lib/utils';
import { Product } from '../lib/shopify/types';

export default async function Home() {
  const collections = await getCollections();

  let featuredProducts: Product[] = [];

  try {
    if (collections.length > 0) {
      featuredProducts = await getCollectionProducts({ collection: collections[0].handle });
    } else {
      const allProducts = await getProducts({});
      featuredProducts = allProducts.slice(0, 8);
    }
  } catch (error) {
    console.error('Error fetching featured products:', error);
    featuredProducts = [];
  }

  const [lastProduct, ...restProducts] = featuredProducts;

  return (
    <PageLayout>
      <div className="contents md:grid md:grid-cols-12 md:gap-sides">
        <HomeSidebar collections={collections} />
        <div className="flex relative flex-col grid-cols-2 col-span-8 w-full md:grid">
          <div className="fixed top-0 left-0 z-10 w-full pointer-events-none base-grid py-sides">
            <div className="col-span-8 col-start-5">
              <div className="hidden px-6 lg:block">
                <Badge variant="outline-secondary">latest drop</Badge>
              </div>
            </div>
          </div>
          {featuredProducts.length > 0 && (
            <>
              <LatestProductCard className="col-span-2" product={lastProduct} principal />

              {restProducts.map((product: any, index: number) => (
                <LatestProductCard
                  className="col-span-1"
                  key={product.id}
                  product={product}
                  labelPosition={getLabelPosition(index)}
                />
              ))}
            </>
          )}
        </div>
      </div>
    </PageLayout>
  );
}

import { cn } from '@/lib/utils';
import Image from 'next/image';
import { FeaturedProductLabel } from './featured-product-label';
import { Product } from '@/lib/shopify/types';
import Link from 'next/link';

interface LatestProductCardProps {
  product: Product;
  principal?: boolean;
  className?: string;
  labelPosition?: 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';
}

export function LatestProductCard({
  product,
  principal = false,
  className,
  labelPosition = 'bottom-right',
}: LatestProductCardProps) {
  if (principal) {
    return (
      <div className={cn('min-h-fold flex flex-col relative', className)}>
        <Link href={`/product/${product.handle}`} className="size-full flex-1 flex flex-col" prefetch>
          <Image
            priority
            src={product.featuredImage.url}
            alt={product.featuredImage.altText}
            width={1000}
            height={100}
            quality={100}
            className="object-cover size-full flex-1"
          />
        </Link>
        <div className="absolute bottom-0 left-0 grid w-full grid-cols-4 gap-6 pointer-events-none max-md:contents p-sides">
          <FeaturedProductLabel
            className="col-span-3 col-start-2 pointer-events-auto 2xl:col-start-3 2xl:col-span-2 shrink-0"
            product={product}
            principal
          />
        </div>
      </div>
    );
  }

  return (
    <div className={cn('relative', className)}>
      <Link href={`/product/${product.handle}`} className="block w-full aspect-square" prefetch>
        <Image
          src={product.featuredImage.url}
          alt={product.featuredImage.altText}
          width={1000}
          height={100}
          className="object-cover size-full"
        />
      </Link>

      <div
        className={cn(
          'absolute flex p-sides inset-0 items-end pointer-events-none justify-end',
          labelPosition === 'top-left' && 'md:justify-start md:items-start',
          labelPosition === 'top-right' && 'md:justify-end md:items-start',
          labelPosition === 'bottom-left' && 'md:justify-start md:items-end',
          labelPosition === 'bottom-right' && 'md:justify-end md:items-end'
        )}
      >
        <FeaturedProductLabel className="pointer-events-auto" product={product} />
      </div>
    </div>
  );
}

